from collections import defaultdict
tot = defaultdict(float); totk = defaultdict(float)
for r in rows:
    tot[(r["owner"], r["scope"])] += r["aufwand_pt_ohne_kenney"]; totk[(r["owner"], r["scope"])] += r["aufwand_pt_mit_kenney"]
owners = ["Sophie","3D-Artist","Outsourcing"]
for label,T in (("OHNE Kenney",tot),("MIT Kenney (Proben gemessen, Rest Schaetzung)",totk)):
    print(label); print("Owner;KERN;5K;ARCH;Summe")
    for o in owners:
        k=T[(o,"KERN")]; f5=T[(o,"5K")]; ar=T[(o,"ARCH")]
        print(f"{o};{k:.1f};{f5:.1f};{ar:.1f};{k+f5+ar:.1f}")
    print("Gesamt;%.1f;%.1f;%.1f;%.1f" % (sum(T[(o,'KERN')] for o in owners), sum(T[(o,'5K')] for o in owners), sum(T[(o,'ARCH')] for o in owners), sum(T.values())))
    print()
from collections import Counter
c = Counter(r["kenney_abdeckung"].split(":")[0].split(" (")[0] for r in rows)
print("Kenney-Abdeckung:", dict(c))
